    }
    test("homo_sapiens illumina vcf stratification") {

        when {
            process {
                """
                // generate stratification tsv file
            stratification_tsv = Channel.of("multi_intervals\\tmulti_intervals.bed.gz")
                    .collectFile(name:"stratification.tsv", newLine:true)
                    .map { [[id:'test'], it] }

                input[0] = [
                        [ id:'test' ], // meta map
